arduino.setup:
#define MQ2_AO_PIN ${AO}
#define MQ2_DO_PIN ${DO}
pinMode(MQ2_DO_PIN, INPUT);
Serial.println("MQ-2 Gas Sensor ready.");

arduino.loop:
int analogVal = analogRead(MQ2_AO_PIN);
int digitalVal = digitalRead(MQ2_DO_PIN);
Serial.print("MQ-2 AO: ");
Serial.print(analogVal);
Serial.print("  DO: ");
Serial.println(digitalVal == LOW ? "GAS DETECTED" : "Clear");
delay(1000);
